INSERT INTO "public"."programs" ("id", "program_id", "name", "description", "status", "created_at", "updated_at", "requirements") VALUES ('0c179498-6d57-4b4f-b66a-f7e4930a285c', 'prog-istitmar-tpe', 'Istitmar TPE', 'Programme Maroc PME destiné aux très petites entreprises industrielles existantes ou en amorçage disposant d''un chiffre d''affaires annuel inférieur ou égal à 10 MDH. Soutien sous forme de prime à l''investissement matériel et immatériel.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:15:19.700236+00', '[{"name":"Pièce d''identité du représentant légal","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Registre de commerce","mandatory":true,"document_type":"rc","validity_required":false},{"name":"Statuts de l''entreprise","mandatory":true,"document_type":"statuts","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Déclarations / liasses fiscales","mandatory":true,"document_type":"liasses_fiscales","validity_required":true},{"name":"États financiers","mandatory":true,"document_type":"etats_financiers","validity_required":false},{"name":"Plan d''investissement","mandatory":true,"document_type":"plan_investissement","validity_required":false},{"name":"Devis des investissements","mandatory":true,"document_type":"devis","validity_required":false}]'), ('0f41a629-305b-44b8-bafb-ef0c89e7cb1e', 'prog-tatwir-vert', 'TATWIR Croissance Verte', 'Offre intégrée de Maroc PME destinée aux PME industrielles pour les projets de croissance verte, efficacité énergétique, énergies renouvelables, technologies propres, produits éco-conçus et développement de filières industrielles vertes.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:13:05.219169+00', '[{"name":"Pièce d''identité du représentant légal","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Registre de commerce","mandatory":true,"document_type":"rc","validity_required":false},{"name":"Statuts de l''entreprise","mandatory":true,"document_type":"statuts","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Plan d''affaires","mandatory":true,"document_type":"business_plan","validity_required":false},{"name":"Plan d''investissement vert","mandatory":true,"document_type":"plan_investissement","validity_required":false},{"name":"Devis des équipements","mandatory":true,"document_type":"devis","validity_required":false},{"name":"Étude / diagnostic environnemental ou énergétique","mandatory":true,"document_type":"etude_environnementale","validity_required":false}]'), ('14b12ab1-c22d-4455-9fc8-64752e144b91', 'prog-indh-inclusion', 'INDH - Inclusion économique', 'Dispositif d''appui dans le cadre de l''Initiative Nationale pour le Développement Humain visant notamment l''inclusion économique, l''accompagnement des initiatives locales et le développement des activités génératrices de revenus. Les conditions et appels dépendent du territoire et du programme concerné.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:13:56.330509+00', '[{"name":"Pièce d''identité du porteur de projet","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Plan d''affaires / étude du projet","mandatory":true,"document_type":"business_plan","validity_required":false},{"name":"Devis des investissements","mandatory":true,"document_type":"devis","validity_required":false},{"name":"Justificatif du statut juridique de la structure","mandatory":true,"document_type":"justificatif_statut","validity_required":false},{"name":"Attestation CNSS","mandatory":false,"document_type":"attestation_cnss","validity_required":true}]'), ('2235b51c-0db2-4cd0-987d-9b138db3f220', 'prog-mowakaba', 'MOWAKABA', 'Programme Maroc PME d''accompagnement et d''appui financier couvrant notamment le conseil et l''expertise technique, la transformation digitale, le développement des produits, les marchés, la stratégie et l''excellence opérationnelle.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:13:43.669439+00', '[{"name":"Pièce d''identité du représentant légal","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Registre de commerce","mandatory":true,"document_type":"rc","validity_required":false},{"name":"Statuts de l''entreprise","mandatory":true,"document_type":"statuts","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"États financiers","mandatory":true,"document_type":"etats_financiers","validity_required":false},{"name":"Plan d''action / plan de transformation","mandatory":true,"document_type":"plan_action","validity_required":false}]'), ('2cf21294-ddf2-4198-8f4a-e958363deb74', 'prog-intelaka-rural', 'Intelak Al Moustatmir Al Qarawi', 'Dispositif Intelaka destiné aux projets et entreprises implantés en milieu rural. Il facilite l''accès au financement d''investissement et aux crédits à court terme avec intervention de Tamwilcom.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:10:38.300929+00', '[{"name":"Pièce d''identité","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Justificatif de domicile","mandatory":true,"document_type":"justificatif_domicile","validity_required":false},{"name":"Business plan / Plan d''affaires","mandatory":true,"document_type":"business_plan","validity_required":false},{"name":"Devis des investissements","mandatory":true,"document_type":"devis","validity_required":false},{"name":"Attestation fiscale","mandatory":false,"document_type":"attestation_fiscale","validity_required":true}]'), ('574c9b2d-6b07-4176-ac1c-df643fab1ba1', 'prog-istitmar-pme', 'Istitmar PME', 'Programme Maroc PME destiné aux petites et moyennes entreprises industrielles ayant un chiffre d''affaires annuel compris entre 10 et 200 MDH. Soutien à l''investissement matériel et immatériel sous forme de prime à l''investissement.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:12:45.721511+00', '[{"name":"Pièce d''identité du représentant légal","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Registre de commerce","mandatory":true,"document_type":"rc","validity_required":false},{"name":"Statuts de l''entreprise","mandatory":true,"document_type":"statuts","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Déclarations / liasses fiscales","mandatory":true,"document_type":"liasses_fiscales","validity_required":true},{"name":"États financiers","mandatory":true,"document_type":"etats_financiers","validity_required":false},{"name":"Plan d''investissement","mandatory":true,"document_type":"plan_investissement","validity_required":false},{"name":"Devis des investissements","mandatory":true,"document_type":"devis","validity_required":false}]'), ('a38f8bec-9053-4ac6-b308-d0815fad310b', 'prog-green-invest', 'Green Invest', 'Mécanisme de cofinancement de projets d''investissement des entreprises marocaines portant notamment sur les énergies renouvelables, l''efficacité énergétique, les technologies propres et les investissements verts.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:11:10.897499+00', '[{"name":"Pièce d''identité du représentant légal","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Registre de commerce","mandatory":true,"document_type":"rc","validity_required":false},{"name":"Statuts de l''entreprise","mandatory":true,"document_type":"statuts","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Plan d''affaires / Plan d''investissement","mandatory":true,"document_type":"business_plan","validity_required":false},{"name":"Devis des investissements","mandatory":true,"document_type":"devis","validity_required":false},{"name":"Étude / justificatif environnemental","mandatory":true,"document_type":"etude_impact_environnemental","validity_required":false}]'), ('bb4ae4d5-1568-4f49-9ac3-f24ddd2e125b', 'prog-forsa', 'FORSA', 'Programme gouvernemental destiné aux porteurs de projets avec formation, accompagnement et financement. Les éditions réalisées proposaient un financement pouvant atteindre 100 000 DH, comprenant une subvention et un prêt d''honneur sans intérêt.', 'HISTORICAL', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:14:09.075982+00', '[{"name":"Pièce d''identité","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Présentation / plan du projet","mandatory":true,"document_type":"business_plan","validity_required":false},{"name":"Devis des investissements","mandatory":false,"document_type":"devis","validity_required":false}]'), ('c0277fbb-ce2e-421b-bd77-467c8f09a33c', 'prog-start-tpe', 'Start-TPE', 'Financement destiné aux besoins en fonds de roulement des entreprises en démarrage ayant bénéficié d''un crédit d''investissement garanti dans le cadre d''Intelaka.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:10:53.456231+00', '[{"name":"Pièce d''identité","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Attestation / justificatif du crédit d''investissement","mandatory":true,"document_type":"attestation_credit","validity_required":false},{"name":"Justificatif d''activité","mandatory":true,"document_type":"justificatif_activite","validity_required":false}]'), ('c3ac36b1-e37c-4a71-adae-193ac87cec8f', 'prog-tatwir-rd', 'TATWIR R&D et Innovation', 'Programme Maroc PME destiné aux entreprises industrielles, startups et projets collaboratifs portant sur la recherche et développement, le développement technologique, l''innovation produit ou procédé et la valorisation des brevets.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:13:27.737772+00', '[{"name":"Pièce d''identité du représentant légal","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Registre de commerce","mandatory":true,"document_type":"rc","validity_required":false},{"name":"Statuts de l''entreprise","mandatory":true,"document_type":"statuts","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Dossier de projet R&D / Innovation","mandatory":true,"document_type":"projet_rd","validity_required":false},{"name":"Plan de financement du projet","mandatory":true,"document_type":"plan_financement","validity_required":false},{"name":"Devis et offres fournisseurs","mandatory":true,"document_type":"devis","validity_required":false}]'), ('f7374af1-f356-4307-acb4-f16199715c8e', 'prog-intelaka', 'Intelaka / Damane Intelak', 'Programme intégré d''appui et de financement de l''entrepreneuriat destiné notamment aux jeunes porteurs de projets, auto-entrepreneurs, micro-entreprises et TPE. Damane Intelak facilite l''accès aux crédits d''investissement et d''exploitation via une garantie publique.', 'ACTIVE', '2026-09-08 11:06:50.579469+00', '2026-09-08 11:10:23.043926+00', '[{"name":"Pièce d''identité","mandatory":true,"document_type":"piece_identite","validity_required":false},{"name":"Relevé d''identité bancaire","mandatory":true,"document_type":"rib","validity_required":false},{"name":"Justificatif de domicile","mandatory":true,"document_type":"justific